<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/lifecycle/prospects.php';
function pub_gate():void{if(crm_query("SELECT state FROM nd_schema_migrations WHERE version='023_publication'")->fetchColumn()!=='applied')crm_fail(503,'Раздел публикаций ещё не установлен.');}
function pub_record(int $id,bool $lock=false):array{$p=crm_query('SELECT * FROM nd_publications WHERE id=?'.($lock?' FOR UPDATE':''),[$id])->fetch();if(!$p)crm_fail(404,'Материал не найден.');return $p;}
function pub_version(int $id):array{$v=crm_query('SELECT * FROM nd_publication_versions WHERE id=?',[$id])->fetch();if(!$v||!hash_equals($v['checksum'],hash('sha256',$v['body_json'])))crm_fail(404,'Редакция не найдена.');$v['body']=json_decode($v['body_json'],true,512,JSON_THROW_ON_ERROR);return $v;}
function pub_head(array $p):array{$id=crm_query('SELECT id FROM nd_publication_versions WHERE publication_id=? AND revision_number=?',[$p['id'],$p['head_revision']])->fetchColumn();return pub_version((int)$id);}
function pub_permission(array $p,array $v):array|false{if(!$p['order_id'])return false;$kind=$p['kind']==='portfolio'?'portfolio_permission':'review_permission';return crm_query("SELECT g.* FROM nd_publication_permissions g JOIN nd_lc_document_bindings b ON b.id=g.binding_id JOIN nd_lc_templates t ON t.id=b.template_id WHERE g.version_id=? AND g.state='GRANTED' AND b.state='AGREED' AND b.order_id=? AND t.kind=? ORDER BY g.id DESC LIMIT 1",[$v['id'],$p['order_id'],$kind])->fetch();}
function pub_live(array $p,array $v):bool{return $p['state']==='PUBLISHED'&&(int)$p['published_version_id']===(int)$v['id']&&(int)$v['publication_id']===(int)$p['id']&&(!$p['order_id']||pub_permission($p,$v)!==false);}
function pub_categories():array{return ['landing'=>'Лендинги','website'=>'Сайты','ai'=>'ИИ-агенты и автоматизация','app'=>'Веб-приложения'];}
function pub_text_reference(array $b):string{return $b['title']."\n".($b['short_description']??'')."\n".$b['text']."\nЗадача: ".($b['task']??'')."\nВыполнено: ".($b['work']??'')."\nРезультат: ".($b['result']??'')."\nПроект: ".($b['project_url']??'')."\nКатегория: ".(pub_categories()[$b['category']??'website']??'')."\nНа главной: ".(($b['featured']??false)?'да':'нет');}
function pub_media_reference(array $media):string{return 'Точный состав смешанной галереи: '.count($media).' элементов. SHA-256 манифеста: '.hash('sha256',lc_json($media));}
function pub_body(array $d):array{
 $title=cc_text($d,'title',190);$text=cc_text($d,'text',10000);$display=cc_text($d,'display_name',190,false);$media=$d['media']??[];if(!is_array($media)||!array_is_list($media))crm_fail(422,'Проверьте список медиа. Число элементов не ограничено; действуют лимиты хранения.');$out=[];
 foreach($media as $m){if(!is_array($m))crm_fail(422,'Проверьте медиа.');$id=cc_id($m['id']??null);$file=crm_query('SELECT id,kind,external_url,mime,checksum,deleted_at FROM nd_publication_media WHERE id=?',[$id])->fetch();if(!$file||$file['deleted_at']!==null)crm_fail(422,'Один из файлов удалён. Уберите его из черновика или замените.');$item=['id'=>$id,'mime'=>$file['mime'],'checksum'=>$file['checksum'],'caption'=>cc_text($m,'caption',1000,false)];if($file['kind']==='external')$item['external_url']=$file['external_url'];$out[]=$item;}
 $category=$d['category']??'website';if(!is_string($category)||!isset(pub_categories()[$category]))crm_fail(422,'Выберите категорию существующей услуги.');$url=cc_text($d,'project_url',2000,false);if($url!==''){if(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https'||parse_url($url,PHP_URL_USER)!==null||parse_url($url,PHP_URL_PASS)!==null||parse_url($url,PHP_URL_QUERY)!==null||parse_url($url,PHP_URL_FRAGMENT)!==null)crm_fail(422,'Укажите публичный HTTPS-адрес проекта без паролей, параметров или секретных фрагментов.');$host=parse_url($url,PHP_URL_HOST);if(!$host||$host==='localhost'||str_ends_with($host,'.local')||filter_var($host,FILTER_VALIDATE_IP)&&!filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))crm_fail(422,'Укажите общедоступный адрес проекта.');}
 $cover=$d['cover_id']??null;if($cover!==null){cc_id($cover);$found=false;foreach($out as $m)if($m['id']===$cover&&str_starts_with($m['mime'],'image/'))$found=true;if(!$found)crm_fail(422,'Обложка должна быть изображением из этой галереи.');}
 return ['title'=>$title,'text'=>$text,'display_name'=>$display,'category'=>$category,'short_description'=>cc_text($d,'short_description',1000,false),'task'=>cc_text($d,'task',2000,false),'work'=>cc_text($d,'work',2000,false),'result'=>cc_text($d,'result',2000,false),'project_url'=>$url,'featured'=>($d['featured']??false)===true,'cover_id'=>$cover,'media'=>$out];
}

function pub_save(array $d,bool $insideTransaction=false):array{$write=function()use($d){$id=$d['id']??null;$p=$id?pub_record(cc_id($id),true):null;if($p)crm_version($d,$p);if($p&&$p['state']==='ARCHIVED')crm_fail(409,'Верните материал из архива в черновики перед редактированием.');if($p&&!array_key_exists('media',$d))$d['media']=pub_head($p)['body']['media'];$body=pub_body($d);if(!$p){$kind=$d['kind']??'';$slug=cc_text($d,'slug',80);if(!in_array($kind,['portfolio','review'],true)||!preg_match('/^[a-z][a-z0-9-]{2,79}$/D',$slug))crm_fail(422,'Выберите тип и адрес материала.');$order=$d['order_id']??null;if($order!==null)crm_record('orders',cc_id($order),true);if($kind==='review'&&$order===null)crm_fail(422,'Отзыв относится к реальному заказу; выберите заказ.');crm_query('INSERT INTO nd_publications(kind,slug,order_id) VALUES (?,?,?)',[$kind,$slug,$order]);$p=pub_record((int)db()->lastInsertId(),true);}$n=(int)$p['head_revision']+1;$raw=lc_json($body);crm_query('INSERT INTO nd_publication_versions(publication_id,revision_number,body_json,checksum) VALUES (?,?,?,?)',[$p['id'],$n,$raw,hash('sha256',$raw)]);$vid=(int)db()->lastInsertId();crm_query("UPDATE nd_publications SET head_revision=?,state=IF(state='PUBLISHED','PUBLISHED','DRAFT'),version=version+1 WHERE id=?",[$n,$p['id']]);$head=pub_version($vid);$head['body']=pub_summary($head['body']);return ['ok'=>true,'record'=>pub_record((int)$p['id']),'head'=>$head];};return $insideTransaction?$write():crm_idempotent('publication/save',$d,$write);}
function pub_publish(array $d,bool $publish):array{return crm_idempotent('publication/'.($publish?'publish':'unpublish'),$d,function()use($d,$publish){$p=pub_record(cc_id($d['id']??null),true);crm_version($d,$p);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите точную публикацию/снятие владельцем.');$v=pub_head($p);if(($d['checksum']??'')!==$v['checksum'])crm_fail(409,'Редакция изменилась. Обновите просмотр.');if($publish)foreach($v['body']['media'] as $m)if(!crm_query('SELECT id FROM nd_publication_media WHERE id=? AND deleted_at IS NULL',[$m['id']])->fetchColumn())crm_fail(409,'В черновике есть удалённое медиа. Замените его или уберите перед публикацией.');if($publish&&$p['order_id']&&!pub_permission($p,$v))crm_fail(409,'Нужно отдельное добровольное разрешение на точное содержание этой редакции.');if($publish&&!$p['order_id']&&($d['own_materials_confirmed']??false)!==true)crm_fail(422,'Подтвердите собственные права и отсутствие чужих клиентских материалов.');$position=$d['sort_order']??(int)$p['sort_order'];if(!is_int($position)||abs($position)>100000)crm_fail(422,'Проверьте порядок.');crm_query('UPDATE nd_publications SET state=?,published_version_id=?,sort_order=?,version=version+1 WHERE id=?',[$publish?'PUBLISHED':'UNPUBLISHED',$publish?$v['id']:null,$position,$p['id']]);lc_audit(['type'=>'owner','id'=>1],'publication',(int)$p['id'],$publish?'published':'unpublished',null,['version_id'=>$v['id'],'checksum'=>$v['checksum'],'reason'=>cc_text($d,'reason',2000,false)]);$grant=$p['order_id']?pub_permission($p,$v):false;if($grant)pub_event((int)$grant['id'],['type'=>'owner','id'=>1],$publish?'PUBLISHED':'UNPUBLISHED',$v['checksum'],cc_text($d,'reason',2000));return ['ok'=>true,'record'=>pub_record((int)$p['id'])];});}
function pub_event(int $id,array $a,string $action,string $hash,string $reason):void{crm_query('INSERT INTO nd_publication_permission_events(permission_id,actor_type,actor_id,action,checksum,reason) VALUES (?,?,?,?,?,?)',[$id,$a['type'],$a['id'],$action,$hash,$reason]);}
function pub_request(array $d):array{return crm_idempotent('publication/permission/request',$d,function()use($d){$p=pub_record(cc_id($d['id']??null),true);if(!$p['order_id'])crm_fail(422,'Клиентское разрешение относится к заказу.');$v=pub_head($p);if(($d['checksum']??'')!==$v['checksum'])crm_fail(409,'Проверьте точную редакцию.');$b=lc_binding(['type'=>'owner','id'=>1],cc_id($d['binding_id']??null));$expected=$p['kind']==='portfolio'?'portfolio_permission':'review_permission';if((int)$b['order_id']!==(int)$p['order_id']||$b['kind']!==$expected||$b['state']!=='AGREED')crm_fail(409,'Нужен отдельно подписанный и проверенный документ разрешения этого заказа и типа.');$snap=json_decode($b['input_snapshot'],true);$fields=$snap['package_fields']??[];$ref=$p['kind']==='portfolio'?($fields['permission.version']??''):($fields['review.publication_terms']??'');$body=$v['body'];$expectedText=$p['kind']==='portfolio'?pub_text_reference($body):$body['text'];$actualText=$p['kind']==='portfolio'?($fields['permission.material_list']??''):($fields['review.text']??'');if($expectedText!==$actualText||$p['kind']==='review'&&($fields['review.display_name']??'')!==$body['display_name'])crm_fail(409,'Текст и имя в отдельном подписанном разрешении отличаются от редакции публикации.');$mediaReference=pub_media_reference($body['media']);$actualMedia=$p['kind']==='portfolio'?($fields['permission.attachment_list']??''):($fields['review.photo_reference']??'');if($body['media']&&$mediaReference!==$actualMedia&&lc_json($body['media'])!==$actualMedia)crm_fail(409,'Состав медиа и подписи должны совпадать с отдельным разрешением.');if(($body['featured']??false)===true&&!in_array('https://neurodelo.pro/',preg_split('/[\s,;]+/u',$p['kind']==='portfolio'?($fields['permission.channels']??''):($fields['review.channels']??'')),true))crm_fail(409,'Разрешение должно охватывать показ выбранной работы на главной странице.');if(!str_contains($ref,$v['checksum']))crm_fail(409,'Отдельное разрешение должно указывать SHA-256 точной публикационной редакции. Подготовьте документ по этой версии.');$o=crm_record('orders',(int)$p['order_id']);$old=crm_query('SELECT id FROM nd_publication_permissions WHERE version_id=?',[$v['id']])->fetchColumn();if($old)return ['ok'=>true,'id'=>(int)$old];crm_query('INSERT INTO nd_publication_permissions(version_id,binding_id,customer_id) VALUES (?,?,?)',[$v['id'],$b['id'],$o['customer_id']]);$id=(int)db()->lastInsertId();pub_event($id,['type'=>'owner','id'=>1],'REQUESTED',$v['checksum'],'Отдельный добровольный запрос на точное содержание; отказ не влияет на заказ.');return ['ok'=>true,'id'=>$id];});}
function pub_visible_permission(array $a,array $g):void{if($a['type']==='customer'&&(int)$g['customer_id']!==$a['customer_id'])crm_fail(404,'Разрешение не найдено.');if($a['type']==='prospect'){$b=ps_binding($a['session'],(int)$g['binding_id']);if((int)$b['order_id']!==(int)$a['order_id'])crm_fail(404,'Разрешение не найдено.');}}
function pub_decide(array $a,array $d):array{return crm_atomic(function()use($a,$d){$g=crm_query('SELECT * FROM nd_publication_permissions WHERE id=? FOR UPDATE',[cc_id($d['id']??null)])->fetch();if(!$g)crm_fail(404,'Разрешение не найдено.');pub_visible_permission($a,$g);if($a['type']==='owner')crm_fail(403,'Владелец не предоставляет согласие за клиента.');$v=pub_version((int)$g['version_id']);$decision=$d['decision']??'';if(($d['checksum']??'')!==$v['checksum']||($d['confirm']??false)!==true||!in_array($decision,['GRANTED','DECLINED','REVOKED'],true))crm_fail(422,'Выберите отдельное решение по точной редакции.');if($g['state']===$decision)return ['ok'=>true,'replayed'=>true];if($decision==='REVOKED'&&$g['state']!=='GRANTED'||$decision!=='REVOKED'&&$g['state']!=='REQUESTED')crm_fail(409,'Решение уже записано.');crm_query('UPDATE nd_publication_permissions SET state=?,reason=?,decided_at=UTC_TIMESTAMP() WHERE id=?',[$decision,cc_text($d,'reason',2000,false),$g['id']]);pub_event((int)$g['id'],$a,$decision,$v['checksum'],cc_text($d,'reason',2000,false));if(in_array($decision,['REVOKED','DECLINED'],true))crm_query("UPDATE nd_publications SET state='UNPUBLISHED',published_version_id=NULL,version=version+1 WHERE id=? AND published_version_id=?",[$v['publication_id'],$v['id']]);return ['ok'=>true,'published'=>false];});}

function pub_review_submit(array $a,array $d):array{
 if(!in_array($a['type'],['customer','prospect'],true))crm_fail(403,'Отзыв передаёт заказчик.');$order=cc_id($d['order_id']??null);$o=crm_record('orders',$order);if((int)$o['customer_id']!==(int)$a['customer_id']||$a['type']==='prospect'&&$order!==(int)$a['order_id'])crm_fail(404,'Заказ не найден.');$f=crm_query('SELECT delivery_state FROM nd_lc_order_flow WHERE order_id=?',[$order])->fetchColumn();if(!in_array($f,['HANDOVER_PREPARED','HANDED_OVER'],true))crm_fail(409,'Отзыв запрашивается при завершении заказа.');if(($d['confirm_private_submission']??false)!==true)crm_fail(422,'Подтвердите приватную передачу отзыва владельцу без разрешения публикации.');
 return crm_idempotent('publication/review-submit:'.$a['type'].':'.$a['id'],$d,function()use($a,$d,$order,$o){$body=['title'=>'Отзыв о заказе '.$o['number'],'text'=>cc_text($d,'text',15000),'display_name'=>cc_text($d,'display_name',190,false),'media'=>[]];$result=pub_save($body+['kind'=>'review','slug'=>'review-'.bin2hex(random_bytes(10)),'order_id'=>$order,'request_key'=>hash('sha256','review-private:'.$a['type'].':'.$a['id'].':'.$d['request_key'])],true);$e=['publication_id'=>$result['record']['id'],'checksum'=>$result['head']['checksum'],'publication_permission'=>false];if($a['type']==='prospect')ps_event($a['id'],'prospect','private_review_submitted',$e);else lc_audit($a,'order',$order,'private_review_submitted',null,$e);return ['ok'=>true,'submitted'=>true,'published'=>false];});
}

function pub_gallery_change(array $d):array{return crm_idempotent('publication/gallery',$d,function()use($d){$p=pub_record(cc_id($d['id']??null),true);crm_version($d,$p);$v=pub_head($p);if(($d['checksum']??'')!==$v['checksum'])crm_fail(409,'Редакция галереи изменилась. Обновите просмотр.');$body=$v['body'];$items=$body['media'];$action=$d['action']??'';
 if($action==='add'){$new=$d['media']??null;if(!is_array($new)||!array_is_list($new)||!$new)crm_fail(422,'Выберите файлы или поддерживаемое видео.');foreach($new as $item)$items[]=$item;}
 else{$index=$d['index']??null;if(!is_int($index)||!isset($items[$index]))crm_fail(409,'Элемент галереи изменился. Обновите страницу.');if($action==='remove')array_splice($items,$index,1);elseif($action==='replace')$items[$index]=['id'=>cc_id($d['media_id']??null),'caption'=>cc_text($d,'caption',1000,false)];elseif($action==='caption')$items[$index]['caption']=cc_text($d,'caption',1000,false);elseif($action==='cover'){if(!str_starts_with($items[$index]['mime'],'image/'))crm_fail(422,'Для обложки выберите изображение.');$body['cover_id']=$items[$index]['id'];}elseif($action==='move'){$to=$d['to']??null;if(!is_int($to)||$to<0||$to>=count($items))crm_fail(422,'Выберите позицию в галерее.');$item=array_splice($items,$index,1)[0];array_splice($items,$to,0,[$item]);}else crm_fail(422,'Выберите действие галереи.');}
 $body['media']=$items;if(($body['cover_id']??null)!==null&&!in_array($body['cover_id'],array_column($items,'id'),true))$body['cover_id']=null;return pub_save($body+['id'=>(int)$p['id'],'version'=>(int)$p['version'],'request_key'=>$d['request_key']],true);});}
function pub_archive(array $d,bool $restore=false):array{return crm_idempotent('publication/archive',$d,function()use($d,$restore){$p=pub_record(cc_id($d['id']??null),true);crm_version($d,$p);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите перенос материала.');crm_query('UPDATE nd_publications SET state=?,published_version_id=NULL,version=version+1 WHERE id=?',[$restore?'DRAFT':'ARCHIVED',$p['id']]);lc_audit(['type'=>'owner','id'=>1],'publication',(int)$p['id'],$restore?'restored_to_draft':'archived',null,[]);return ['ok'=>true,'record'=>pub_record((int)$p['id'])];});}
function pub_summary(array $body):array{$summary=$body;$summary['media_count']=count($body['media']);$summary['gallery_manifest']=pub_media_reference($body['media']);$cover=null;foreach($body['media'] as $m)if(str_starts_with($m['mime'],'image/')&&($cover===null||($body['cover_id']??null)===$m['id'])){$cover=$m;if(($body['cover_id']??null)===$m['id'])break;}$summary['cover']=$cover;$summary['media']=[];return $summary;}
